import { test, expect } from '@playwright/test';

test.describe('Search Results with Debounced Input', () => {
  let requestCount = 0;
  const baseUrl = 'http://localhost:3000';

  test.beforeEach(async ({ page }) => {
    requestCount = 0;

    // Mock the search API endpoint
    await page.route('**/api/search*', async (route) => {
      requestCount++;
      const url = new URL(route.request().url());
      const query = url.searchParams.get('q') || '';

      // Simulate API response with delay
      await new Promise(resolve => setTimeout(resolve, 100));

      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          results: [
            { id: 1, title: `Result for "${query}"` },
            { id: 2, title: `Another result for "${query}"` }
          ],
          query: query,
          timestamp: Date.now()
        })
      });
    });

    await page.goto(baseUrl);
  });

  test('should debounce search requests by 300ms', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });
    const resultsContainer = page.getByRole('region', { name: /search results/i });

    // Type characters with rapid input (faster than 300ms debounce)
    await searchInput.click();
    await searchInput.type('t', { delay: 50 });
    await searchInput.type('e', { delay: 50 });
    await searchInput.type('s', { delay: 50 });
    await searchInput.type('t', { delay: 50 });

    // At this point, no API request should have been made yet
    // because we're typing faster than the debounce interval
    const initialRequestCount = requestCount;
    expect(initialRequestCount).toBe(0);

    // Wait for debounce to complete (300ms) plus some buffer
    await page.waitForTimeout(350);

    // Now exactly one request should have been made
    expect(requestCount).toBe(1);

    // Verify results are displayed
    await expect(resultsContainer).toContainText('Result for "test"');
  });

  test('should update results only after debounce period completes', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });
    const resultsContainer = page.getByRole('region', { name: /search results/i });

    // First search
    await searchInput.click();
    await searchInput.type('hello', { delay: 100 });

    // Wait for debounce
    await page.waitForTimeout(350);
    expect(requestCount).toBe(1);

    await expect(resultsContainer).toContainText('Result for "hello"');

    // Clear and type new search
    await searchInput.clear();
    await searchInput.type('world', { delay: 100 });

    // Wait for debounce
    await page.waitForTimeout(350);
    expect(requestCount).toBe(2);

    await expect(resultsContainer).toContainText('Result for "world"');
  });

  test('should handle rapid consecutive searches with proper debouncing', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });
    const resultsContainer = page.getByRole('region', { name: /search results/i });

    // Type first query
    await searchInput.click();
    await searchInput.type('a', { delay: 50 });
    await searchInput.type('b', { delay: 50 });

    // Wait 200ms (less than debounce)
    await page.waitForTimeout(200);
    expect(requestCount).toBe(0);

    // Continue typing before debounce completes
    await searchInput.type('c', { delay: 50 });
    await searchInput.type('d', { delay: 50 });

    // Wait another 200ms (total 400ms from last keystroke)
    await page.waitForTimeout(200);

    // Should still be only 1 request (debounce resets with each keystroke)
    expect(requestCount).toBe(1);

    await expect(resultsContainer).toContainText('Result for "abcd"');
  });

  test('should display loading state during debounce period', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });
    const loadingIndicator = page.getByRole('status', { name: /loading/i });

    await searchInput.click();
    await searchInput.type('query', { delay: 50 });

    // Check if loading indicator appears during debounce
    const isVisible = await loadingIndicator.isVisible().catch(() => false);

    // Wait for debounce and API response
    await page.waitForTimeout(450);

    // Loading indicator should be gone after results arrive
    await expect(loadingIndicator).not.toBeVisible().catch(() => {
      // It's acceptable if loading indicator doesn't exist
    });
  });

  test('should not make requests for empty search queries', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });

    await searchInput.click();
    await searchInput.type('test', { delay: 50 });

    // Wait for debounce
    await page.waitForTimeout(350);
    expect(requestCount).toBe(1);

    // Clear the input
    await searchInput.clear();

    // Wait for debounce
    await page.waitForTimeout(350);

    // Should not make additional request for empty query
    expect(requestCount).toBe(1);
  });
});
